local x=np.astype(np.arange(0,"int64"):reshape({0,4}),"float64")
local before=x:tolist()
local out=np.zeros({0,4},"float64")
local y=r:permuted(x,2,out)
deep(y.dtype,"float64","42/(0, 4)/float64/plain/1/out_new dtype")
deep(y:tolist(),{},"42/(0, 4)/float64/plain/1/out_new values")
deep(x:tolist(),{},"42/(0, 4)/float64/plain/1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"c621fbcd16d92688","42/(0, 4)/float64/plain/1/out_new pcg")
cases=cases+1; end
